import{_ as s,r as a,o as r,c as l,e as n,a as i,s as d}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Sorting Records - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuring the behavior","slug":"configuring-the-behavior","link":"#configuring-the-behavior","children":[]},{"level":2,"title":"Displaying the reorder page","slug":"displaying-the-reorder-page","link":"#displaying-the-reorder-page","children":[]},{"level":2,"title":"Override Sortable Partials","slug":"override-sortable-partials","link":"#override-sortable-partials","children":[]},{"level":2,"title":"Extending the model query","slug":"extending-the-model-query","link":"#extending-the-model-query","children":[]}],"relativePath":"1.x/backend/reorder.md","filePath":"1.x/backend/reorder.md"}'),p={name:"1.x/backend/reorder.md"};function c(h,e,u,g,m,b){const o=a("pre-heading"),t=a("post-heading");return r(),l("div",null,[n(o),e[0]||(e[0]=i("h1",null,"Sorting Records",-1)),n(t),e[1]||(e[1]=d(`<p><strong>Reorder behavior</strong> is a controller modifier that provides features for sorting and reordering database records. The behavior provides a page called Reorder using the controller action <code>reorder</code>. This page displays a list of records with a drag handle allowing them to be sorted and in some cases restructured.</p><p>The behavior depends on a <a href="./../database/model.html">model class</a> which must implement one of the following <a href="./../database/traits.html">model traits</a>:</p><ol><li><a href="./../database/traits.html#sortable"><code>October\\Rain\\Database\\Traits\\Sortable</code></a></li><li><a href="./../database/traits.html#nestedtree"><code>October\\Rain\\Database\\Traits\\NestedTree</code></a></li></ol><blockquote><p><strong>Note</strong>: If adding sorting to a previously unsorted model under the control of a third party is desired, you can use the <a href="./../database/behaviors.html#sortable"><code>October\\Rain\\Database\\Behaviors\\Sortable</code></a> behavior, which can be dynamically implemented. However, you will need to ensure that the model table has a <code>sort_order</code> column present on it.</p></blockquote><p>In order to use the reorder behavior you should add it to the <code>$implement</code> property of the controller class. Also, the <code>$reorderConfig</code> class property should be defined and its value should refer to the YAML file used for configuring the behavior options.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Shop<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;Backend.Behaviors.ReorderController&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$reorderConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_reorder.yaml&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// [...]</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="configuring-the-behavior"><a href="#configuring-the-behavior" class="header-anchor">#</a> Configuring the behavior</h2><p>The configuration file referred in the <code>$reorderConfig</code> property is defined in YAML format. The file should be placed into the controller&#39;s <a href="./controllers-ajax.html">views directory</a>. Below is an example of a configuration file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Reorder Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token comment"># Reorder Title</span>
<span class="token key atrule">title</span><span class="token punctuation">:</span> Reorder Categories

<span class="token comment"># Attribute name</span>
<span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> title

<span class="token comment"># Model Class name</span>
<span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Shop\\Models\\Category

<span class="token comment"># Toolbar widget configuration</span>
<span class="token key atrule">toolbar</span><span class="token punctuation">:</span>
    <span class="token comment"># Partial for toolbar buttons</span>
    <span class="token key atrule">buttons</span><span class="token punctuation">:</span> reorder_toolbar
</code></pre></div><p>The configuration options listed below can be used.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>used for the page title.</td></tr><tr><td><strong>nameFrom</strong></td><td>specifies which attribute should be used as a label for each record.</td></tr><tr><td><strong>modelClass</strong></td><td>a model class name, the record data is loaded from this model.</td></tr><tr><td><strong>toolbar</strong></td><td>reference to a Toolbar Widget configuration file, or an array with configuration.</td></tr></tbody></table></div><h2 id="displaying-the-reorder-page"><a href="#displaying-the-reorder-page" class="header-anchor">#</a> Displaying the reorder page</h2><p>You should provide a <a href="./controllers-ajax.html">view file</a> with the name <strong>reorder.htm</strong>. This view represents the Reorder page that allows users to reorder records. Since reordering includes the toolbar, the view file will consist solely of the single <code>reorderRender</code> method call.</p><pre><code>&lt;?= $this-&gt;reorderRender() ?&gt;
</code></pre><h2 id="override-sortable-partials"><a href="#override-sortable-partials" class="header-anchor">#</a> Override Sortable Partials</h2><p>If you need to override default view of your reorder page, you have to copy</p><ol><li><code>modules/backend/behaviors/reordercontroller/partials/_container.htm</code></li><li><code>modules/backend/behaviors/reordercontroller/partials/_records.htm</code></li></ol><p>in</p><ol><li><code>plugins/yournamespace/yourplugin/yoursortablecontroller/_reorder_container.htm</code></li><li><code>plugins/yournamespace/yourplugin/yoursortablecontroller/_reorder_records.htm</code></li></ol><h2 id="extending-the-model-query"><a href="#extending-the-model-query" class="header-anchor">#</a> Extending the model query</h2><p>The lookup query for the list <a href="./../database/model.html">database model</a> can be extended by overriding the <code>reorderExtendQuery</code> method inside the controller class. This example will ensure that soft deleted records are included in the list data, by applying the <strong>withTrashed</strong> scope to the query:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">reorderExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,22))])}const y=s(p,[["render",c]]);export{f as __pageData,y as default};
